sections.snippet:
.caption{ color:var(--aha-deck-ink-secondary) }
.panel{ background:var(--aha-deck-surface); border:1px solid var(--aha-deck-stroke) }
.option:hover .control{ border-color:var(--aha-deck-stroke-hover) }
.tile:hover{ background:var(--aha-deck-fill-hover) }
.tile:active{ background:var(--aha-deck-fill-active) }

.leaderboard-backdrop{ position:absolute; inset:0; display:grid; place-items:center; background:var(--aha-deck-modal-backdrop) }
.leaderboard{ border-radius:var(--aha-deck-container-radius-lg); padding:var(--aha-deck-container-padding-lg);
  background:var(--aha-deck-modal-fill); box-shadow:inset 0 0 0 1px var(--aha-deck-container-stroke);
  backdrop-filter:blur(var(--aha-blur-md)); color:var(--aha-deck-ink) }
.leaderboard .empty{ border:1px dashed var(--aha-deck-container-stroke-empty); border-radius:var(--aha-deck-container-radius-sm) }
